    magnitude_sum = 0

    for num in arr:
        if num > 0:
            magnitude_sum += num
        elif num < 0:
            magnitude_sum += -num
            product_sign *= -1
        else:
            return 0

    return product_sign * magnitude_sum

def minPath(grid, k):
    from collections import deque

    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_path = None

    def bfs(start_x, start_y):
        nonlocal min_path
        queue = deque([(start_x, start_y, [grid[start_x][start_y]])])

        while queue:
            x, y, path = queue.popleft()

            if len(path) == k:
                if min_path is None or path < min_path:
                    min_path = path
                continue

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    queue.append((nx, ny, path + [grid[nx][ny]]))

    for i in range(n):
        for j in range(n):
            bfs(i, j)

    return min_path

def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
            if len(stack) > 1:
                nested = True
        elif char == ']':
            if not stack:
                return False
            stack.pop()

    return nested and not stack

def sum_squares(lst):
