    return sum(math.ceil(x) ** 2 for x in lst)

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False
    txt = txt.rstrip()
    if len(txt) == 0 or txt[-1] == ' ':
        return False
    return txt[-1].isalpha() and (len(txt) == 1 or txt[-2] == ' ')

def can_arrange(arr):
    if not arr:
        return -1
    for i in range(len(arr) - 1, 0, -1):
        if arr[i] < arr[i - 1]:
            return i
    return -1

def largest_smallest_integers(lst):
    largest_negative = None
    smallest_positive = None

    for num in lst:
        if num < 0:
            if largest_negative is None or num > largest_negative:
                largest_negative = num
        elif num > 0:
            if smallest_positive is None or num < smallest_positive:
                smallest_positive = num

    return (largest_negative, smallest_positive)

def compare_one(a, b):
    def parse_number(value):
        if isinstance(value, str):
            value = value.replace(',', '.')
        return float(value)

    a_parsed = parse_number(a)
    b_parsed = parse_number(b)

    if a_parsed == b_parsed:
        return None
    return a if a_parsed > b_parsed else b

def sum_squares(lst):
    total = 0
    for index, value in enumerate(lst):
        if index % 3 == 0:
            total += value ** 2
        elif index % 4 == 0:
            total += value ** 3
    return total

def words_in_sentence(sentence):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_length_words)

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    index1 = planets.index(planet1)
    index2 = planets.index(planet2)

    if index1 > index2:
        index1, index2 = index2, index1

    return tuple(planets[index1 + 1:index2])

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n < 2:
        return y
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return y
    return x

def double_the_difference(lst):
    if not lst:
        return 0
    return sum(x**2 for x in lst if isinstance(x, int) and x > 0 and x % 2 != 0)

def compare(game, guess):
    result = []
    for score, g in zip(game, guess):
        result.append(abs(score - g))
    return result

def cycpattern_check(word1, word2):
    if not word2:
        return False
    doubled_word2 = word2 + word2
    return word1.find(word2) != -1 or any(doubled_word2[i:i+len(word2)] in word1 for i in range(len(word2)))

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return sides[0]**2 + sides[1]**2 == sides[2]**2

def find_max(words):
    max_word = ""
    max_unique_count = 0

    for word in words:
        unique_chars = len(set(word))
        if (unique_chars > max_unique_count) or (unique_chars == max_unique_count and word < max_word):
            max_unique_count = unique_chars
            max_word = word

    return max_word

def eat(number, need, remaining):
    total_eaten = number
    if remaining >= need:
        total_eaten += need
        remaining -= need
    else:
        total_eaten += remaining
        remaining = 0
    return [total_eaten, remaining]

def do_algebra(operator, operand):
    expression = str(operand[0])
    for i in range(len(operator)):
        expression += f" {operator[i]} {operand[i + 1]}"
    return eval(expression)

def solve(s):
    if any(c.isalpha() for c in s):
        return ''.join(c.upper() if c.islower() else c.lower() for c in s)
    else:
        return s[::-1]

import hashlib

def string_to_md5(text):
    if text == "":
        return None
    return hashlib.md5(text.encode()).hexdigest()
